    return 0

def filter_oddnumbers(nums):
    odd_nums = list(filter(lambda x: x%2 != 1, nums))
    return odd_nums

def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if m == 0:
        return 1
    return (m + 1) * eulerian_num(n - 1, m) + (n - m) * eulerian_num(n - 1, m - 1)

